import sqlite3,re,math
p='/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-hermesagentlearner-1792545801/attempts/daf701f1674f4c4db1b7fbdb00f41b36/system/state/hermes/state.db'; c=sqlite3.connect(p)
def msg(i): return c.execute('select content from messages where id=?',(i,)).fetchone()[0]
def parse_grid(text, marker):
 m=re.search(re.escape(marker)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)',text)
 if not m: raise ValueError(marker)
 H,W=map(int,m.group(1,2)); a=[list(map(int,l.split())) for l in m.group(3).strip().splitlines()]
 assert len(a)==H and all(len(r)==W for r in a)
 return a
def comps(a,color):
 H,W=len(a),len(a[0]); seen=set(); out=[]
 for r in range(H):
  for col in range(W):
   if a[r][col]==color and (r,col) not in seen:
    st=[(r,col)]; seen.add((r,col)); obj=[]
    while st:
     x,y=st.pop();obj.append((x,y))
     for z in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
      if 0<=z[0]<H and 0<=z[1]<W and a[z[0]][z[1]]==color and z not in seen:seen.add(z);st.append(z)
    out.append(sorted(obj))
 return sorted(out,key=lambda o:(o[0],len(o)))
def ds(a,b):
 pairs=[(abs(x-u),abs(y-v)) for x,y in a for u,v in b]
 l1=min(dx+dy for dx,dy in pairs); linf=min(max(dx,dy) for dx,dy in pairs); l2=min(math.sqrt(dx*dx+dy*dy) for dx,dy in pairs)
 return l1,linf,l2, min(pairs)
for idx,oi,target_color in [(898,898,9),(906,906,0)]:
 t=msg(idx); inp=parse_grid(t,'Demo pair '+('1' if idx==898 else '2')+' input'); out=parse_grid(t,'Demo pair '+('1' if idx==898 else '2')+' output')
 changes=[(r,col,inp[r][col],out[r][col]) for r in range(len(inp)) for col in range(len(inp[0])) if inp[r][col]!=out[r][col]]
 print('DEMO',1 if idx==898 else 2,'changes',changes)
 seven=comps(inp,7); marker=comps(inp,target_color)
 print('7 components',[(len(o),(min(r for r,c0 in o),max(r for r,c0 in o),min(c0 for r,c0 in o),max(c0 for r,c0 in o))) for o in seven])
 print(target_color,'components',[(len(o),(min(r for r,c0 in o),max(r for r,c0 in o),min(c0 for r,c0 in o),max(c0 for r,c0 in o))) for o in marker])
 for j,o in enumerate(seven): print(' 7obj',j,'closest marker',min((ds(o,m),k) for k,m in enumerate(marker)))
 print('changed component index',next(j for j,o in enumerate(seven) if any(p0[:2] in set(o) for p0 in changes)))

